def hamming_distance(seq_a, seq_b):
    if len(seq_a) != len(seq_b):
        raise ValueError("Hamming distance requires equal-length sequences")
    return sum(a != b for a, b in zip(seq_a, seq_b))

# General strings
print(hamming_distance("karolin", "kathrin"))  # 3

# Binary strings, via XOR and popcount
def hamming_distance_binary(int_a, int_b):
    return bin(int_a ^ int_b).count("1")

print(hamming_distance_binary(0b10110, 0b11100))  # 2

